const $=id=>document.getElementById(id),cv=$('preview'),ctx=cv.getContext('2d'),DRAFT='darkin.skill.studio.v1',clone=structuredClone;
let p=createSkillProject(),catalog,source,images=new Map(),selected=null,eventId=null,effect=null,page=0,playing=false,loop=false,t=0,live=null,samplePreview=null,active=true,undo=[],redo=[],selectionRequest=0,busy=false;
