const skill=()=>p.skills[selected],event=()=>skill()?.events.find(e=>e.id===eventId),fold=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
