 for(const[id,key]of [['sid','id'],['sname','name'],['kind','kind'],['duration','duration'],['hitAt','hitAt'],['cooldown','cooldown'],['cost','cost'],['range','range'],['animation','animation']]){$(id).value=s?.[key]??'';$(id).disabled=!s}
 $('nativeInfo').textContent=s?.native?'Nguồn: '+s.native.source+' · '+s.native.id+' · cấp '+s.native.rank+' · VFX do bạn ghép, chưa tự chuyển RUN gốc.':'Thiết kế riêng; tên clip chỉ là mã để game gọi hoạt ảnh.';
 const events=s?.events||[];if(!events.some(e=>e.id===eventId))eventId=events[0]?.id||null;$('events').replaceChildren(...events.map(e=>new Option(e.at.toFixed(2)+' s · '+e.effectId+' · '+e.layer,e.id)));$('events').value=eventId||'';const e=event();
 for(const[id,key]of [['at','at'],['eventDuration','duration'],['scale','scale'],['opacity','opacity'],['x','x'],['y','y'],['rotation','rotation'],['anchor','anchor'],['motion','motion'],['layer','layer'],['blend','blend'],['follow','follow']]){const el=$(id);el.disabled=!e;if(el.type==='checkbox')el.checked=!!e?.[key];else el.value=e?.[key]??''}
 const fx=e&&p.effects[e.effectId];$('color').disabled=fx?.group!=='procedural';if(fx?.color)$('color').value=fx.color;$('projectId').value=p.id;$('projectName').value=p.name;$('undo').disabled=!undo.length;$('redo').disabled=!redo.length;$('scrub').max=s?.duration||1;t=Math.min(t,s?.duration||0);$('scrub').value=t;$('play').disabled=!s;$('cast').disabled=!s||s.kind==='passive';$('addEffect').disabled=!effect||!s||busy;
