on('skills','change',()=>{stop();selected=$('skills').value;eventId=null;t=0;render()});on('events','change',()=>{eventId=$('events').value;render()});
on('newSkill','click',()=>{const id=nextId('skill_',Object.keys(p.skills));mutate(q=>q.skills[id]=newVisualSkill(id));selected=id;render();show('skill')});
