for(const[id,key]of [['sid','id'],['sname','name'],['kind','kind'],['duration','duration'],['hitAt','hitAt'],['cooldown','cooldown'],['cost','cost'],['range','range'],['animation','animation']])on(id,'change',()=>{if(!skill())return;const el=$(id),value=el.type==='number'?el.valueAsNumber:el.value.trim();if(key==='id'){if(!skillId(value))throw Error('ID skill chỉ dùng chữ Latin, số, _ hoặc -');if(value!==selected&&Object.hasOwn(p.skills,value))throw Error('ID skill đã tồn tại');const old=selected;mutate(q=>{const s=q.skills[old];delete q.skills[old];s.id=value;q.skills[value]=s});selected=value;render()}else mutate(q=>q.skills[selected][key]=value)});
for(const[id,key]of [['at','at'],['eventDuration','duration'],['scale','scale'],['opacity','opacity'],['x','x'],['y','y'],['rotation','rotation'],['anchor','anchor'],['motion','motion'],['layer','layer'],['blend','blend'],['follow','follow']])on(id,'change',()=>{if(event()){const el=$(id),value=el.type==='checkbox'?el.checked:el.type==='number'?el.valueAsNumber:el.value;mutate(q=>q.skills[selected].events.find(e=>e.id===eventId)[key]=value)}});
on('color','input',()=>{const e=event();if(e&&p.effects[e.effectId].group==='procedural')mutate(q=>q.effects[e.effectId].color=$('color').value)});
on('cloneEvent','click',()=>{if(!event())return;const e=clone(event());e.id=nextId('event_',skill().events.map(e=>e.id));mutate(q=>q.skills[selected].events.push(e));eventId=e.id;render()});on('deleteEvent','click',()=>{if(event())mutate(q=>q.skills[selected].events=q.skills[selected].events.filter(e=>e.id!==eventId))});
function nativeRows(){const query=fold($('skillSearch').value),rows=catalog.skills.filter(s=>fold([s.name,s.id,s.originalName,...s.jobs].join(' ')).includes(query));$('nativeSkills').replaceChildren(...rows.map(s=>new Option(s.name+' · '+s.id+' · '+s.kind,s.id)));nativeInfo()}
function nativeInfo(){const s=catalog?.skills.find(s=>s.id===$('nativeSkills').value);if(!s){$('nativeSkillInfo').textContent='Không có kết quả';return}$('nativeRank').max=s.ranks.length;const rank=Math.max(1,Math.min(s.ranks.length,Number($('nativeRank').value)||1));$('nativeRank').value=rank;const r=s.ranks[rank-1];$('nativeSkillInfo').textContent=`${s.originalName} · ${s.id} · ${s.kind} · cấp ${rank}/${s.ranks.length} · SP ${r.cost??'—'} · hệ số ${r.multiplier??'—'} · CD ${s.native.cd??'—'} s · ${s.source}. ${r.description||''}`}
on('skillSearch','input',nativeRows);on('nativeSkills','change',nativeInfo);on('nativeRank','change',nativeInfo);
on('addNativeSkill','click',()=>{const n=catalog.skills.find(s=>s.id===$('nativeSkills').value);if(!n)return;if(p.skills[n.id])throw Error('Skill này đã có. Chọn trong project hoặc nhân bản để giữ thiết kế cũ.');const rank=Number($('nativeRank').value),r=n.ranks[rank-1];if(!r)throw Error('Cấp skill không hợp lệ');const s={...newVisualSkill(n.id,n.name),kind:n.kind,cooldown:Number.isFinite(n.native.cd)?n.native.cd:0,cost:r.cost??0,native:{...clone(n),rank}};mutate(q=>q.skills[n.id]=s);selected=n.id;eventId=null;t=0;render();show('skill')});
function gallery(){const query=fold($('effectSearch').value),group=$('effectGroup').value,rows=catalog.effects.filter(e=>(group==='all'||e.group===group)&&fold(e.name+' '+e.id).includes(query));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(rows.length/16)-1)));$('effectList').replaceChildren(...rows.slice(page*16,page*16+16).map(e=>{const b=document.createElement('button');b.dataset.effect=e.id;b.className=effect?.id===e.id?'selected':'';if(e.frames){const im=new Image();im.src=source.assetURL(e.frames[0].src);im.alt=e.name;im.loading='lazy';b.append(im)}const label=document.createElement('span');label.textContent=e.name;b.append(label);b.title=e.id;b.onclick=safe(async()=>{effect=e;$('effectInfo').textContent=e.preview+' · '+e.source;$('addEffect').disabled=!skill();gallery();await previewEffect(e)});return b}));$('catalogInfo').textContent=`${catalog.skills.length} skill gốc · ${rows.length}/${catalog.effects.length} VFX · chọn VFX rồi thêm vào timeline.`;$('pageInfo').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/16));$('prevEffects').disabled=page===0;$('nextEffects').disabled=(page+1)*16>=rows.length}
on('effectSearch','input',()=>{page=0;gallery()});on('effectGroup','change',()=>{page=0;gallery()});on('prevEffects','click',()=>{page--;gallery()});on('nextEffects','click',()=>{page++;gallery()});
async function previewEffect(fx){const token=++selectionRequest,temp=createSkillProject();temp.effects[fx.id]=fx;const loaded=await loadSkillImages(temp,s=>source.assetURL(s));if(token!==selectionRequest)return;stop();samplePreview={fx,images:loaded,started:performance.now(),duration:fx.frames?.reduce((n,f)=>n+f.duration,0)||.7};msg('Đang xem mẫu '+fx.id+' · chưa thêm vào project')}
async function addEffect(fx){if(!skill())throw Error('Tạo hoặc chọn skill trước');if(busy)throw Error('Đang tải ảnh');const identity=p,skillIdentity=selected;busy=true;$('addEffect').disabled=true;try{const temp=createSkillProject();temp.effects[fx.id]=fx;const loaded=await loadSkillImages(temp,s=>source.assetURL(s));if(p!==identity||selected!==skillIdentity)throw Error('Skill đã đổi trong lúc tải; thử lại');busy=false;const id=nextId('event_',skill().events.map(e=>e.id)),duration=Math.max(.1,Math.min(5,fx.frames?.reduce((n,f)=>n+f.duration,0)||.7)),e={id,effectId:fx.id,at:0,duration,scale:1,x:0,y:0,rotation:0,opacity:1,anchor:'target',follow:false,motion:'still',layer:'high',blend:'normal'};mutate(q=>{q.effects[fx.id]||=clone(fx);q.skills[selected].duration=Math.max(q.skills[selected].duration,duration);q.skills[selected].events.push(e)});for(const[src,img]of loaded)images.set(src,img);eventId=id;t=duration*.5;render();show('timeline')}finally{busy=false;render()}}
on('addEffect','click',()=>{if(effect)return addEffect(effect)});on('uploadEffect','click',()=>$('effectFile').click());on('effectFile','change',async()=>{const f=$('effectFile').files[0];if(!f)return;try{if(!['image/png','image/webp','image/jpeg'].includes(f.type)||f.size>8*1024*1024)throw Error('Ảnh PNG/WebP/JPG tối đa 8 MB');const raw=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)}),im=new Image();await new Promise((ok,no)=>{im.onload=ok;im.onerror=no;im.src=raw});if(im.naturalWidth*im.naturalHeight>16777216)throw Error('Ảnh tối đa 16 triệu pixel');const c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,0,0);await addEffect({id:'custom_'+Date.now().toString(36),name:f.name,group:'image',frames:[{src:c.toDataURL('image/png'),w:Math.min(400,im.naturalWidth),h:Math.min(400,im.naturalWidth)*im.naturalHeight/im.naturalWidth,ax:.5,ay:.5,duration:.6}],source:'Ảnh riêng'})}finally{$('effectFile').value=''}});
on('play','click',()=>{live=null;playing=!playing;if(t>=skill().duration)t=0;$('play').textContent=playing?'Ⅱ Tạm dừng':'▶ Phát timeline'});on('stop','click',()=>{stop();t=0});on('scrub','input',()=>{stop();t=Number($('scrub').value)});on('cast','click',()=>{if(!skill())return;if(!live)live=new SkillPlayer(p,{onEvent:e=>{if(e.type==='hit-marker')msg('Mốc hit · '+e.skillId+' · chỉ tín hiệu, không gây sát thương')}});playing=false;const result=live.cast(selected,{caster,target});msg(result?'Đang dùng thử · '+skill().name:'Skill bị động hoặc đang hồi chiêu: '+live.remaining(selected).toFixed(1)+' s')});
cv.addEventListener('pointerdown',e=>{const r=cv.getBoundingClientRect(),z=Number($('zoom').value);target.x=(e.clientX-r.left-r.width/2)/z;target.y=(e.clientY-r.top-r.height*.65)/z;msg('Đã đổi điểm mục tiêu')});
for(const[id,from,to]of [['undo',()=>undo,()=>redo],['redo',()=>redo,()=>undo]])on(id,'click',async()=>{if(busy)throw Error('Đang tải');const stack=from();if(!stack.length)return;busy=true;try{const next=stack.at(-1),loaded=await loadSkillImages(next,s=>source.assetURL(s));to().push(p);stack.pop();p=next;images=loaded;stop();persist();render()}finally{busy=false;render()}});
for(const[id,key]of [['projectId','id'],['projectName','name']])on(id,'change',()=>mutate(q=>q[key]=$(id).value.trim()));
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function portable(){const q=clone(p),used=new Set(Object.values(q.skills).flatMap(s=>s.events.map(e=>e.effectId)));q.effects=Object.fromEntries(Object.entries(q.effects).filter(([id])=>used.has(id)));const loaded=await loadSkillImages(q,s=>source.assetURL(s)),embedded=new Map();for(const e of Object.values(q.effects))for(const f of e.frames||[]){if(!embedded.has(f.src)){const im=loaded.get(f.src),c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,0,0);embedded.set(f.src,c.toDataURL('image/png'))}f.src=embedded.get(f.src)}return validateSkillProject(q)}
const runtime=async()=>{const r=await fetch(new URL('./runtime.mjs',import.meta.url));if(!r.ok)throw Error('Không tải được bộ phát');return r.text()};
on('save','click',async()=>download(p.id+'.skill-project.json',JSON.stringify(await portable())));on('export','click',async()=>download(p.id+'.skill-pack.json',JSON.stringify({format:'darkin-skill-pack-v1',project:await portable(),runtime:{version:1,file:'skill-runtime.mjs',source:await runtime()},usage:'Use SkillPlayer and embedded effect frames; cast/update/draw low, high, glow. onEvent cast requests character animation; hit-marker is a visual timing signal, NEVER authoritative damage. Game/server validates skill ownership, mana, cooldown, range, targets, hits and rewards. Imported native skill rank data is metadata, not original RUN functions or shaders. See effects/README.md.'})));on('runtime','click',async()=>download('skill-runtime.mjs',await runtime(),'text/javascript'));
on('open','click',()=>$('projectFile').click());on('projectFile','change',async()=>{const f=$('projectFile').files[0];if(!f)return;if(f.size>40*1024*1024)throw Error('Gói tối đa 40 MB');const next=clone(validateSkillProject(JSON.parse(await f.text()))),loaded=await loadSkillImages(next,s=>source.assetURL(s));undo.push(p);redo=[];p=next;images=loaded;selected=null;stop();persist();render();msg('Đã mở '+p.name);$('projectFile').value=''});on('reset','click',()=>{mutate(q=>{q.skills={};q.effects={}});selected=null;render()});
on('back','click',()=>{stop();if(parent!==window)parent.postMessage({type:'darkin.effects.close'},location.origin);else location.href='../index.html'});window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;if(e.data?.type==='darkin.effects.pause'){active=false;stop()}if(e.data?.type==='darkin.effects.resume')active=true});
let last=0;function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(active){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1,z=Number($('zoom').value);const w=Math.round(r.width*d),h=Math.round(r.height*d);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle=$('night').checked?'#101c30':'#36544b';ctx.fillRect(0,0,r.width,r.height);ctx.translate(r.width/2,r.height*.65);ctx.scale(z,z);if(playing&&skill()){t+=dt;if(t>skill().duration){if($('loop').checked)t=0;else{t=skill().duration;playing=false;$('play').textContent='▶ Phát timeline'}}}if(live)live.update(dt);const instance={caster,casterRef:caster,target};const draw=layer=>{if(samplePreview){if(layer==='high'){const sp=samplePreview,f=sp.fx.frames?.[0],scale=f?Math.min(1,300/f.w,200/f.h):1;drawSkillEvent(ctx,{duration:sp.duration,scale,x:0,y:0,rotation:0,opacity:1,anchor:'caster',follow:false,motion:'still',blend:'normal'},sp.fx,instance,Math.min((now-sp.started)/1000,sp.duration*.8),sp.images)}}else if(live)live.draw(ctx,images,{layer});else if(skill())for(const e of skill().events)if(e.layer===layer)drawSkillEvent(ctx,e,p.effects[e.effectId],instance,t-e.at,images)};draw('low');for(const[pt,color,label]of [[caster,'#d3ed92','Người phát'],[target,'#ffbd80','Mục tiêu']]){ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(pt.x,pt.y,18,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(pt.x,pt.y-20,12,0,Math.PI*2);ctx.fill();ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillText(label,pt.x,pt.y+22)}draw('high');if($('night').checked){ctx.fillStyle='#101a4b44';ctx.fillRect(-r.width/z,-r.height/z,r.width*2/z,r.height*2/z)}draw('glow');$('scrub').value=t;$('time').textContent=t.toFixed(2)+' s';}requestAnimationFrame(frame)}
safe(async()=>{source=await connectSource(!!window.STUDIO_GITHUB,new URL('../',import.meta.url));const r=await fetch(new URL('./catalog.json',import.meta.url));if(!r.ok)throw Error('Không tải được thư viện');catalog=await r.json();try{const old=localStorage.getItem(DRAFT);if(old){p=clone(validateSkillProject(JSON.parse(old)));images=await loadSkillImages(p,s=>source.assetURL(s))}}catch{msg('Không đọc được nháp; dùng project trắng, có thể mở file đã lưu')}nativeRows();gallery();render();msg('Sẵn sàng · '+catalog.skills.length+' skill · '+catalog.effects.length+' VFX · dữ liệu gốc + timeline hình ảnh độc lập');requestAnimationFrame(frame)})();
